	["while"] = true, ["continue"] = true, ["export"] = true, ["type"] = true, ["self"] = true,
}

local CODE_BUILTINS = {
	["game"] = true, ["workspace"] = true, ["script"] = true, ["require"] = true,
	["print"] = true, ["warn"] = true, ["error"] = true, ["assert"] = true,
	["pairs"] = true, ["ipairs"] = true, ["pcall"] = true, ["xpcall"] = true,
