			ImageColor3 = theme.Accent,
			Size = UDim2.new(0, 12, 0, 12),
			LayoutOrder = 1,
		})

		countryLabel = CreateInstance("TextLabel", {
			Name = "Country",
			Parent = row2,
			BackgroundTransparency = 1,
			AutomaticSize = Enum.AutomaticSize.X,
			Size = UDim2.new(0, 0, 1, 0),
